// Import the private payload generated by generate_lazada_preload.py.
// Requires the migration in supabase_lazada_sync_v298.sql to be installed first.
// Never copy the service-role key or private payload into a public web asset.
const fs = require('node:fs');
const path = require('node:path');

const env = Object.fromEntries(fs.readFileSync(path.join(__dirname, '.env'), 'utf8')
  .split(/\r?\n/).filter(line => /^\s*[A-Za-z_][A-Za-z0-9_]*\s*=/.test(line))
  .map(line => { const index = line.indexOf('='); return [line.slice(0, index).trim(), line.slice(index + 1).trim()]; }));
const base = env.SUPABASE_URL?.replace(/\/$/, '');
const key = env.SUPABASE_SERVICE_ROLE_KEY;
if (!base || !key) throw new Error('SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required in .env');
const payload = JSON.parse(fs.readFileSync(path.join(__dirname, 'lazada_private_import.json'), 'utf8'));
const headers = { apikey:key, Authorization:'Bearer ' + key, 'Content-Type':'application/json', Prefer:'resolution=merge-duplicates,return=representation' };

async function request(endpoint, options = {}) {
  const response = await fetch(base + '/rest/v1/' + endpoint, { ...options, headers:{...headers,...options.headers} });
  const body = await response.json().catch(() => null);
  if (!response.ok) throw new Error(`${response.status}: ${body?.code || ''} ${body?.message || 'request failed'}`);
  return body;
}

async function main() {
  const shops = await request('shops?select=id,name&name=eq.sealthai');
  if (shops.length !== 1) throw new Error(`Expected one sealthai shop; found ${shops.length}`);
  const shopId = shops[0].id;
  await request('lazada_summary_items?select=order_item_id&limit=1');
  let synced = 0;
  for (let offset = 0; offset < payload.length; offset += 100) {
    const batch = payload.slice(offset, offset + 100).map(item => ({
      shop_id:shopId, order_item_id:item.orderItemId, order_id:item.orderId, payload:item
    }));
    const result = await request('lazada_summary_items?on_conflict=shop_id,order_item_id', {
      method:'POST', body:JSON.stringify(batch)
    });
    if (!Array.isArray(result) || result.length !== batch.length) throw new Error(`Server confirmed ${result?.length || 0}/${batch.length} rows at offset ${offset}`);
    synced += result.length;
  }
  const confirmed = await request('lazada_summary_items?select=order_item_id&shop_id=eq.' + encodeURIComponent(shopId) + '&limit=1000');
  const expected = new Set(payload.map(item => item.orderItemId));
  const seen = new Set(confirmed.map(item => item.order_item_id));
  if ([...expected].some(id => !seen.has(id))) throw new Error('Post-import verification failed: some order items are missing');
  console.log(JSON.stringify({synced,verified:expected.size,finance_transactions:payload.reduce((n,item)=>n+item.transactions.length,0)}));
}
main().catch(error => { console.error('Lazada import failed:', error.message); process.exitCode = 1; });
